<h1 class="h2">Document verification queue</h1><div class="row g-3 mb-4"><?php foreach($counts as $key=>$count):?><div class="col-4"><div class="card"><div class="card-body"><strong class="h3"><?=e($count)?></strong><div><?=e(ucfirst($key))?></div></div></div></div><?php endforeach;?></div><form class="card card-body mb-4" method="get"><div class="row g-2"><div class="col-md-6"><input class="form-control" name="q" maxlength="255" placeholder="Reference, application, member or email" value="<?=e($filter['q']??'')?>"></div><div class="col-md-3"><select class="form-select" name="status"><?php foreach(Ishep\Services\DocumentStatus::ALL as $item):?><option value="<?=e($item)?>" <?=($filter['status']??'pending')===$item?'selected':''?>><?=e(ucfirst($item))?></option><?php endforeach;?></select></div><div class="col-md-3"><button class="btn btn-primary w-100">Filter</button></div></div></form><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Reference</th><th>Member</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$documents):?><tr><td colspan="5" class="text-center p-5">No matching documents.</td></tr><?php endif;?><?php foreach($documents as $document):?><tr><td><?=e($document['document_reference'])?><br><small><?=e($document['application_number'])?></small></td><td><?=e($document['name'])?><br><small><?=e($document['email'])?></small></td><td><?=e($document['document_type_name'])?></td><td><?=e(ucfirst($document['verification_status']))?></td><td><a href="<?=e(url('/admin/documents/'.$document['document_reference']))?>">Review</a></td></tr><?php endforeach;?></tbody></table></div></div>
